    await dwrite('/entities/'+externalRecord+'/configuration',{expectedRevision:1,tagIds:[externalTag],values:[{fieldId:externalField,value:deposit2},{fieldId:ownedField,value:deposit2}],edges:[]},'PUT');
    // Even budget history, reversals and template references must not block pruning.
