    await sql.query("INSERT INTO charge.budget_transfers(workspace_id,plan_id,operation_id,from_bucket_id,to_bucket_id,amount_minor,reversal_of,snapshot) VALUES($1,$2,$3,$4,$5,100,$6,'{}')",[dw,ownedBudget,opB,bucketB,bucketA,transferA]);
    const ownerIds=(await sql.query('SELECT id FROM charge.owned_entity_ids($1,$2)',[dw,aggregate.ledgerId])).rows.map(r=>r.id);
    ds=await dstate();const agg=ds.goals.find((g:any)=>g.id===aggregate.id);
    await dwrite('/entities/'+aggregate.id,{expectedRevision:agg.revision},'DELETE');
    ds=await dstate();const deletedGoal=ds.trash.find((g:any)=>g.id===aggregate.id);
    assert.equal(deletedGoal.saved_minor,49000);assert.equal(deletedGoal.target_minor,15000000);assert.equal(deletedGoal.plan_name,'新电脑');
    assert(!ds.trash.some((g:any)=>g.id===removedFirst));
