    await dwrite('/savings-plans/'+aggregate.id+'/permanent',{...permanentBody,expectedRevision:999},'DELETE',409);
    // Inject a late failure: the complete transaction, including deleted history,
    // must roll back and leave the plan recoverable.
    await sql.query(`CREATE FUNCTION charge.reject_test_purge() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
      IF OLD.id='${aggregate.id}' THEN RAISE EXCEPTION 'test rollback' USING ERRCODE='23514'; END IF; RETURN OLD; END $$;
      CREATE TRIGGER reject_test_purge BEFORE DELETE ON charge.entities FOR EACH ROW EXECUTE FUNCTION charge.reject_test_purge()`);
    await dwrite('/savings-plans/'+aggregate.id+'/permanent',permanentBody,'DELETE',409);
    assert.equal((await sql.query('SELECT count(*)::int n FROM charge.entities WHERE id=ANY($1::uuid[])',[ownerIds])).rows[0].n,ownerIds.length);
    assert((await dstate()).trash.some((g:any)=>g.id===aggregate.id));
    await sql.query('DROP TRIGGER reject_test_purge ON charge.entities; DROP FUNCTION charge.reject_test_purge()');
    const purged=(await dwrite('/savings-plans/'+aggregate.id+'/permanent',permanentBody,'DELETE')).json();
    assert.equal(purged.purgedCount,ownerIds.length);assert.equal(purged.permanent,true);
    assert.deepEqual((await dwrite('/savings-plans/'+aggregate.id+'/permanent',permanentBody,'DELETE')).json(),purged);
    assert.equal((await sql.query('SELECT count(*)::int n FROM charge.entities WHERE id=ANY($1::uuid[])',[ownerIds])).rows[0].n,0);
    assert.equal((await sql.query('SELECT count(*)::int n FROM charge.budget_plans WHERE id=$1',[ownedBudget])).rows[0].n,0);
    assert.equal((await sql.query('SELECT count(*)::int n FROM charge.budget_transfers WHERE plan_id=$1',[ownedBudget])).rows[0].n,0);
    assert.equal((await sql.query('SELECT count(*)::int n FROM charge.relation_edges WHERE source_id=ANY($1::uuid[]) OR target_id=ANY($1::uuid[])',[ownerIds])).rows[0].n,0);
    assert.equal((await sql.query('SELECT count(*)::int n FROM charge.entity_field_values WHERE value_entity=ANY($1::uuid[]) OR field_id=ANY($1::uuid[])',[ownerIds])).rows[0].n,0);
    await dwrite('/entities/'+aggregate.id+'/restore',{},'POST',404);
    await dwrite('/savings-plans/'+aggregate.id+'/permanent',{expectedRevision:deletedGoal.revision},'DELETE',404);
    const afterPurge=await dstate();assert(afterPurge.goals.some((g:any)=>g.id===keep.id));assert(afterPurge.goals.some((g:any)=>g.id===recreated.id));
    assert(afterPurge.tags.some((g:any)=>g.id===externalTag));assert(afterPurge.fields.some((g:any)=>g.id===externalField));assert(afterPurge.relations.some((g:any)=>g.id===externalRelation));
    assert(afterPurge.transactions.some((t:any)=>t.id===externalRecord));assert(!afterPurge.trash.some((g:any)=>ownerIds.includes(g.id)));
    const recreatedAfterPurge=(await dwrite('/savings-plans',{parentId:deletionUser.ws.root_id,name:'新电脑',targetMinor:15000000})).json();assert.notEqual(recreatedAfterPurge.id,aggregate.id);
    // The ledger entry point produces the same complete plan card and pruning boundary.
    await dwrite('/entities/'+recreatedAfterPurge.ledgerId,{expectedRevision:1},'DELETE');
    const deletedLedger=(await dstate()).trash.find((g:any)=>g.id===recreatedAfterPurge.ledgerId);
    assert.equal(deletedLedger.plan_name,'新电脑');assert.equal(deletedLedger.target_minor,15000000);assert.equal(deletedLedger.saved_minor,0);
    await dwrite('/savings-plans/'+recreatedAfterPurge.id+'/permanent',{expectedRevision:2},'DELETE',409);
    const ledgerPurged=(await dwrite('/savings-plans/'+deletedLedger.id+'/permanent',{expectedRevision:deletedLedger.revision},'DELETE')).json();
    assert.equal(ledgerPurged.purgedCount,3);
    await dwrite('/entities/'+recreatedAfterPurge.id+'/restore',{},'POST',404);
    const adminSession=(await request('POST','/v1/auth/login',{username:'test_admin',password:'administrator-password-123'})).json();
    const at=adminSession.accessToken;
    await request('GET',path('/state'),undefined,at);
    await request('POST',path('/ledgers'),{name:'管理员',ledgerType:'expense',parentId:a.ws.root_id,operationId:randomUUID()},at,422);
    await request('PATCH','/v1/admin/users/'+b.session.user.id,{role:'user',disabled:true,deleted:false,reason:'停用测试'},at);
    await request('GET','/v1/workspaces',undefined,b.session.accessToken,401);
    await request('PATCH','/v1/admin/users/'+adminSession.user.id,{role:'user',disabled:false,deleted:false,reason:'最后管理员测试'},at,409);
    await request('PUT','/v1/admin/settings/registration',{enabled:false,reason:'测试关闭注册'},at);
    await request('POST','/v1/auth/register',{username:'registration_off',password:'personal-password-123'},undefined,403);
    await request('POST','/v1/me/password',{oldPassword:'personal-password-123',newPassword:'updated-password-123'},auth);
    await request('GET','/v1/workspaces',undefined,auth,401);
