    // Exercise the exact operations SQL against this disposable DB only.
    const accountsBefore=(await sql.query('SELECT * FROM charge.app_users ORDER BY id')).rows;
    const membersBefore=(await sql.query('SELECT * FROM charge.workspace_members ORDER BY workspace_id,user_id')).rows;
    const sessionsBefore=(await sql.query('SELECT * FROM charge.auth_sessions ORDER BY id')).rows;
